declare module "@sanity/client" {
  interface SanityQueries {
    '\n  *[\n    _type == "assessment" &&\n    lesson._ref == $lessonId &&\n    reviewStatus == "approved" &&\n    sourceStatus == "current" &&\n    !(_id in path("drafts.**")) &&\n    !(_id in path("versions.**")) &&\n    count(*[\n      _type == "assessment" &&\n      familyId == ^.familyId &&\n      version > ^.version &&\n      reviewStatus == "approved" &&\n      sourceStatus == "current" &&\n      !(_id in path("drafts.**")) &&\n      !(_id in path("versions.**"))\n    ]) == 0\n  ] | order(familyId asc, version desc)[0...50] {\n    _id,\n    _rev,\n    familyId,\n    version,\n    "lessonId": lesson._ref,\n    type,\n    responseFormat,\n    question,\n    "options": options[] { "id": _key, text }\n  }\n': LESSON_PRACTICE_ITEMS_QUERY_RESULT;
    '\n  *[\n    _type == "assessment" &&\n    lesson._ref == $lessonId &&\n    reviewStatus == "approved" &&\n    sourceStatus == "current" &&\n    !(_id in path("drafts.**")) &&\n    !(_id in path("versions.**")) &&\n    lesson->_type == "lesson" &&\n    count(*[\n      _type == "assessment" &&\n      familyId == ^.familyId &&\n      version > ^.version &&\n      reviewStatus == "approved" &&\n      sourceStatus == "current" &&\n      !(_id in path("drafts.**")) &&\n      !(_id in path("versions.**"))\n    ]) == 0\n  ] | order(familyId asc, version desc)[0...50] {\n    "item": {\n      _id,\n      _rev,\n      familyId,\n      version,\n      "lessonId": lesson._ref,\n      type,\n      responseFormat,\n      question,\n      "options": options[] { "id": _key, text }\n    },\n    "primaryConceptRef": primaryConcept._ref,\n    "firstSeconds": math::min(sourceChunkRefs[].startSeconds)\n  }\n': LESSON_CHECK_CANDIDATES_QUERY_RESULT;
    '\n  *[\n    _type == "assessment" &&\n    _id == $assessmentId &&\n    reviewStatus == "approved" &&\n    sourceStatus == "current" &&\n    !(_id in path("drafts.**")) &&\n    !(_id in path("versions.**")) &&\n    lesson->_type == "lesson" &&\n    count(*[\n      _type == "assessment" &&\n      familyId == ^.familyId &&\n      version > ^.version &&\n      reviewStatus == "approved" &&\n      sourceStatus == "current" &&\n      !(_id in path("drafts.**")) &&\n      !(_id in path("versions.**"))\n    ]) == 0\n  ][0] {\n    _id,\n    _rev,\n    familyId,\n    version,\n    "lessonId": lesson._ref,\n    type,\n    responseFormat,\n    question,\n    "options": options[] { "id": _key, text }\n  }\n': SERVABLE_ASSESSMENT_QUERY_RESULT;
    '\n  *[\n    _type == "assessment" &&\n    _id == $assessmentId &&\n    reviewStatus == "approved" &&\n    sourceStatus == "current" &&\n    !(_id in path("drafts.**")) &&\n    !(_id in path("versions.**")) &&\n    lesson->_type == "lesson"\n  ][0] {\n    _id,\n    familyId,\n    version,\n    "lessonId": lesson._ref,\n    "optionIds": options[]._key,\n    "correctOptionId": answerKey.correctOptionId,\n    "primaryConceptRef": primaryConcept._ref\n  }\n': GRADING_ASSESSMENT_QUERY_RESULT;
    '\n  *[\n    _type == "assessment" &&\n    _id == $assessmentId &&\n    reviewStatus == "approved" &&\n    sourceStatus == "current" &&\n    !(_id in path("drafts.**")) &&\n    !(_id in path("versions.**")) &&\n    lesson->_type == "lesson"\n  ][0] {\n    _id,\n    familyId,\n    version,\n    "optionIds": options[]._key,\n    "correctOptionId": answerKey.correctOptionId,\n    "direction": hints.direction,\n    "keyConcept": hints.keyConcept,\n    "solution": hints.solution\n  }\n': HINT_LADDER_QUERY_RESULT;
    '\n  *[\n    _type == "concept" &&\n    !(_id in path("drafts.**")) &&\n    !(_id in path("versions.**"))\n  ] | order(_id asc)[0...2000] {\n    "id": _id,\n    conceptId,\n    reviewStatus,\n    "mergedInto": mergedInto._ref,\n    "splitInto": splitInto[]._ref\n  }\n': CONCEPT_NODES_QUERY_RESULT;
    '\n  *[_type == "category" && defined(slug.current)] | order(title asc) {\n    \n  _id,\n  title,\n  "slug": slug.current\n,\n    description,\n    "courseCount": count(*[_type == "course" && category._ref == ^._id])\n  }\n': CATEGORIES_QUERY_RESULT;
    '\n  *[_type == "category" && slug.current == $slug][0] {\n    \n  _id,\n  title,\n  "slug": slug.current\n,\n    description,\n    "courses": *[_type == "course" && category._ref == ^._id && defined(slug.current)]\n      | order(popular desc, title asc) { \n  _id,\n  title,\n  "slug": slug.current,\n  summary,\n  level,\n  priceDisplay,\n  popular,\n  studentCountDisplay,\n  coverImage { \n  _type,\n  alt,\n  hotspot,\n  crop,\n  asset->{\n    _id,\n    url,\n    metadata { lqip, dimensions { width, height, aspectRatio } }\n  }\n },\n  instructor->{ \n  _id,\n  name,\n  "slug": slug.current,\n  expertise,\n  photo { \n  _type,\n  alt,\n  hotspot,\n  crop,\n  asset->{\n    _id,\n    url,\n    metadata { lqip, dimensions { width, height, aspectRatio } }\n  }\n }\n },\n  category->{ \n  _id,\n  title,\n  "slug": slug.current\n },\n  "moduleCount": count(modules),\n  "lessonCount": count(modules[].lessons[]),\n  "durationSeconds": math::sum(modules[].lessons[]->durationSeconds)\n }\n  }\n': CATEGORY_BY_SLUG_QUERY_RESULT;
    '\n  *[_type == "course" && defined(slug.current)]\n    | order(popular desc, title asc) {\n    \n  _id,\n  title,\n  "slug": slug.current,\n  summary,\n  level,\n  priceDisplay,\n  popular,\n  studentCountDisplay,\n  coverImage { \n  _type,\n  alt,\n  hotspot,\n  crop,\n  asset->{\n    _id,\n    url,\n    metadata { lqip, dimensions { width, height, aspectRatio } }\n  }\n },\n  instructor->{ \n  _id,\n  name,\n  "slug": slug.current,\n  expertise,\n  photo { \n  _type,\n  alt,\n  hotspot,\n  crop,\n  asset->{\n    _id,\n    url,\n    metadata { lqip, dimensions { width, height, aspectRatio } }\n  }\n }\n },\n  category->{ \n  _id,\n  title,\n  "slug": slug.current\n },\n  "moduleCount": count(modules),\n  "lessonCount": count(modules[].lessons[]),\n  "durationSeconds": math::sum(modules[].lessons[]->durationSeconds)\n\n  }\n': COURSES_QUERY_RESULT;
    '\n  *[_type == "course" && defined(slug.current)].slug.current\n': COURSE_SLUGS_QUERY_RESULT;
    '\n  *[_type == "course" && slug.current == $slug][0] {\n    \n  _id,\n  title,\n  "slug": slug.current,\n  summary,\n  level,\n  priceDisplay,\n  popular,\n  studentCountDisplay,\n  coverImage { \n  _type,\n  alt,\n  hotspot,\n  crop,\n  asset->{\n    _id,\n    url,\n    metadata { lqip, dimensions { width, height, aspectRatio } }\n  }\n },\n  instructor->{ \n  _id,\n  name,\n  "slug": slug.current,\n  expertise,\n  photo { \n  _type,\n  alt,\n  hotspot,\n  crop,\n  asset->{\n    _id,\n    url,\n    metadata { lqip, dimensions { width, height, aspectRatio } }\n  }\n }\n },\n  category->{ \n  _id,\n  title,\n  "slug": slug.current\n },\n  "moduleCount": count(modules),\n  "lessonCount": count(modules[].lessons[]),\n  "durationSeconds": math::sum(modules[].lessons[]->durationSeconds)\n,\n    instructor->{ \n  _id,\n  name,\n  "slug": slug.current,\n  expertise,\n  photo { \n  _type,\n  alt,\n  hotspot,\n  crop,\n  asset->{\n    _id,\n    url,\n    metadata { lqip, dimensions { width, height, aspectRatio } }\n  }\n }\n, bio },\n    learningOutcomes[] { _key, icon, title, description },\n    modules[] {\n      _key,\n      title,\n      summary,\n      lessons[]->{ \n  _id,\n  title,\n  "slug": slug.current,\n  durationSeconds,\n  freePreview,\n  poster { \n  _type,\n  alt,\n  hotspot,\n  crop,\n  asset->{\n    _id,\n    url,\n    metadata { lqip, dimensions { width, height, aspectRatio } }\n  }\n }\n }\n    }\n  }\n': COURSE_BY_SLUG_QUERY_RESULT;
    '\n  *[_type == "instructor" && defined(slug.current)] | order(name asc) {\n    \n  _id,\n  name,\n  "slug": slug.current,\n  expertise,\n  photo { \n  _type,\n  alt,\n  hotspot,\n  crop,\n  asset->{\n    _id,\n    url,\n    metadata { lqip, dimensions { width, height, aspectRatio } }\n  }\n }\n,\n    "courseCount": count(*[_type == "course" && instructor._ref == ^._id])\n  }\n': INSTRUCTORS_QUERY_RESULT;
    '\n  *[_type == "instructor" && slug.current == $slug][0] {\n    \n  _id,\n  name,\n  "slug": slug.current,\n  expertise,\n  photo { \n  _type,\n  alt,\n  hotspot,\n  crop,\n  asset->{\n    _id,\n    url,\n    metadata { lqip, dimensions { width, height, aspectRatio } }\n  }\n }\n,\n    bio,\n    "courses": *[_type == "course" && instructor._ref == ^._id && defined(slug.current)]\n      | order(title asc) { \n  _id,\n  title,\n  "slug": slug.current,\n  summary,\n  level,\n  priceDisplay,\n  popular,\n  studentCountDisplay,\n  coverImage { \n  _type,\n  alt,\n  hotspot,\n  crop,\n  asset->{\n    _id,\n    url,\n    metadata { lqip, dimensions { width, height, aspectRatio } }\n  }\n },\n  instructor->{ \n  _id,\n  name,\n  "slug": slug.current,\n  expertise,\n  photo { \n  _type,\n  alt,\n  hotspot,\n  crop,\n  asset->{\n    _id,\n    url,\n    metadata { lqip, dimensions { width, height, aspectRatio } }\n  }\n }\n },\n  category->{ \n  _id,\n  title,\n  "slug": slug.current\n },\n  "moduleCount": count(modules),\n  "lessonCount": count(modules[].lessons[]),\n  "durationSeconds": math::sum(modules[].lessons[]->durationSeconds)\n }\n  }\n': INSTRUCTOR_BY_SLUG_QUERY_RESULT;
    '\n  *[_type == "lesson" && slug.current == $slug][0] {\n    _id,\n    _rev,\n    title,\n    "slug": slug.current,\n    videoUrl,\n    poster { \n  _type,\n  alt,\n  hotspot,\n  crop,\n  asset->{\n    _id,\n    url,\n    metadata { lqip, dimensions { width, height, aspectRatio } }\n  }\n },\n    durationSeconds,\n    freePreview,\n    studentCountDisplay,\n    notes,\n    keyPoints,\n    proTip,\n    resources[] { _key, type, title, description, url },\n    "course": *[_type == "course" && references(^._id)] | order(_createdAt asc)[0] {\n      _id,\n      title,\n      "slug": slug.current,\n      level,\n      coverImage { \n  _type,\n  alt,\n  hotspot,\n  crop,\n  asset->{\n    _id,\n    url,\n    metadata { lqip, dimensions { width, height, aspectRatio } }\n  }\n },\n      instructor->{ \n  _id,\n  name,\n  "slug": slug.current,\n  expertise,\n  photo { \n  _type,\n  alt,\n  hotspot,\n  crop,\n  asset->{\n    _id,\n    url,\n    metadata { lqip, dimensions { width, height, aspectRatio } }\n  }\n }\n },\n      modules[] {\n        _key,\n        title,\n        lessons[]->{ \n  _id,\n  title,\n  "slug": slug.current,\n  durationSeconds,\n  freePreview,\n  poster { \n  _type,\n  alt,\n  hotspot,\n  crop,\n  asset->{\n    _id,\n    url,\n    metadata { lqip, dimensions { width, height, aspectRatio } }\n  }\n }\n }\n      }\n    }\n  }\n': LESSON_BY_SLUG_QUERY_RESULT;
    '\n  *[_type == "lesson" && defined(slug.current)].slug.current\n': LESSON_SLUGS_QUERY_RESULT;
    '\n  *[_type == "course" && defined(slug.current) && references($lessonIds)] | order(title asc) {\n    _id,\n    title,\n    "slug": slug.current,\n    summary,\n    coverImage { \n  _type,\n  alt,\n  hotspot,\n  crop,\n  asset->{\n    _id,\n    url,\n    metadata { lqip, dimensions { width, height, aspectRatio } }\n  }\n },\n    modules[] {\n      _key,\n      lessons[]->{ _id, title, "slug": slug.current }\n    }\n  }\n': MY_LEARNING_COURSES_QUERY_RESULT;
    '\n  *[_type == "lesson" && _id in $lessonIds && defined(slug.current)] {\n    _id,\n    title,\n    "slug": slug.current\n  }\n': LESSONS_BY_IDS_QUERY_RESULT;
    '\n  *[\n    _type == "concept" &&\n    reviewStatus == "approved" &&\n    sourceStatus == "current" &&\n    !(_id in path("drafts.**")) &&\n    !(_id in path("versions.**")) &&\n    count(lessons[@._ref in $lessonIds]) > 0\n  ] | order(_id asc)[0...500].conceptId\n': CONCEPT_IDS_FOR_LESSONS_QUERY_RESULT;
    '\n  *[_type == "progress" && userId == $userId] | order(updatedAt desc) {\n    _id,\n    "lessonId": lesson._ref,\n    completed,\n    completedAt,\n    resumeSeconds,\n    updatedAt\n  }\n': PROGRESS_FOR_USER_QUERY_RESULT;
    '\n  *[_type == "lesson" && _id == $lessonId && !(_id in path("drafts.**")) && !(_id in path("versions.**"))][0] {\n    _id,\n    durationSeconds\n  }\n': PROGRESS_TARGET_LESSON_QUERY_RESULT;
    '\n  *[_type == "progress" && userId == $userId && lesson._ref == $lessonId][0] {\n    _id,\n    "lessonId": lesson._ref,\n    completed,\n    completedAt,\n    resumeSeconds,\n    updatedAt\n  }\n': PROGRESS_FOR_LESSON_QUERY_RESULT;
    '\n  *[_type == "video" && videoId == $videoId] | order(_createdAt asc)[0] {\n    _id,\n    videoId,\n    provider,\n    providerVideoId,\n    sourceUrl,\n    title,\n    durationSeconds,\n    ingestedAt,\n    chapters[] { _key, startSeconds, label },\n    "transcriptChunkCount": count(transcriptChunks)\n  }\n': VIDEO_BY_VIDEO_ID_QUERY_RESULT;
  }
}
